<template>
  <div v-if="payment" class="space-y-4">
    <div class="page-head"><div><RouterLink to="/payments" class="text-[11px] font-bold text-indigo-600">← Payments</RouterLink><h1 class="mt-2">{{ payment.payment_number }}</h1><p>{{ payment.client?.name || 'Unknown client' }} · {{ formatDisplayDate(payment.payment_date) }}</p></div><div class="action-row no-print"><button class="btn btn-soft" @click="printPage">Print receipt</button><button class="btn btn-danger" @click="reversePayment">Reverse payment</button></div></div>
    <div class="grid grid-cols-1 gap-3 sm:grid-cols-4"><div class="card metric"><div class="metric-label">Amount</div><div class="metric-value mt-2">{{ money(payment.amount) }}</div></div><div class="card metric"><div class="metric-label">Method</div><div class="metric-value mt-2 text-lg capitalize">{{ methodLabel(payment.method) }}</div></div><div class="card metric"><div class="metric-label">Allocated</div><div class="metric-value mt-2">{{ money(allocated) }}</div></div><div class="card metric"><div class="metric-label">Reference</div><div class="metric-value mt-2 text-lg break-all">{{ payment.reference || '—' }}</div></div></div>
    <div class="grid grid-cols-1 gap-4 xl:grid-cols-[1fr_1.5fr]"><div class="card p-5"><h2 class="text-sm font-extrabold">Payment details</h2><dl class="mt-4 space-y-4 text-xs"><div><dt class="text-slate-400">Client</dt><dd class="mt-1 font-bold"><RouterLink v-if="payment.client_id" :to="`/clients/${payment.client_id}`" class="text-indigo-600">{{payment.client?.name}}</RouterLink><span v-else>Walk-in</span></dd></div><div><dt class="text-slate-400">Payment date</dt><dd class="mt-1 font-bold">{{formatDisplayDate(payment.payment_date)}}</dd></div><div><dt class="text-slate-400">Notes</dt><dd class="mt-1 font-bold">{{payment.notes || '—'}}</dd></div></dl></div><div class="card overflow-hidden"><div class="px-5 py-4 border-b border-slate-100 dark:border-slate-800"><h2 class="text-sm font-extrabold">Invoice allocations</h2></div><table class="data-table"><thead><tr><th>Invoice</th><th>Invoice total</th><th>Current balance</th><th class="text-right">Allocated</th></tr></thead><tbody><tr v-for="a in payment.allocations || []" :key="a.id"><td><RouterLink :to="`/invoices/${a.invoice_id}`" class="font-bold text-indigo-600">{{a.invoice?.invoice_number || `INV-${a.invoice_id}`}}</RouterLink></td><td>{{money(a.invoice?.total)}}</td><td>{{money(a.invoice?.balance)}}</td><td class="text-right font-bold">{{money(a.amount)}}</td></tr><tr v-if="!(payment.allocations || []).length"><td colspan="4"><div class="empty">No invoice allocations.</div></td></tr></tbody></table></div></div>
  </div><div v-else class="empty">Loading payment...</div>
</template>
<script setup lang="ts">import {formatDate as formatDisplayDate} from '../../utils/date';
import {computed,onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';
const route=useRoute(),router=useRouter(),payment=ref<any>(null),{ask:confirm}=useConfirm(),toast=useToast(); const allocated=computed(()=>payment.value?.allocations?.reduce((s:number,a:any)=>s+Number(a.amount||0),0)||0);
function printPage(){window.print()}
function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))} function methodLabel(v:string){return ({cash:'Cash',bank:'Bank',mpesa:'M-Pesa',airtel_money:'Airtel Money',tigopesa:'Mixx by Yas',halopesa:'HaloPesa',card:'Card',cheque:'Cheque',other:'Other'} as any)[v]||v}
async function load(){payment.value=(await api.get(`/payments/${route.params.id}`)).data}async function reversePayment(){if(!(await confirm({title:'Reverse payment?',message:`${payment.value.payment_number} will be reversed and affected invoice balances recalculated. This action cannot be undone.`,confirmText:'Reverse payment',danger:true})))return;try{await api.delete(`/payments/${payment.value.id}`);toast.success('Payment reversed',`${payment.value.payment_number} was reversed successfully.`);router.push('/payments')}catch(e){toast.error('Action failed',apiError(e))}}onMounted(load)
</script>
